// Platform registry — THE single source for which GPU platforms the site
// offers and how each one is labelled. Every platform selector on every page
// is built from RACKDB (generated by tools/regen_from_variants.py from
// datacenter-design/rack-scale/variants/*.yaml), so adding a variant YAML
// surfaces it site-wide without editing a single page.
//
// This file exists because the site carried FIVE independent hand-written
// 4-entry platform arrays (param_boot, scenario, page_invest, page_plan,
// page_neocloud) plus a sixth in page_rack, while the variant directory had
// grown to eleven — the operator could not see HGX B300, GB200 NVL36, DGX
// B300/H100/H200/B200-HD or Rubin NVL144 anywhere (DSX-25 / spec §F3).
//
// DSX-71 merged DSX-25's registry with the trunk's lifecycle work. There is
// now exactly ONE curated order list in the whole site, the VARIANT_ORDER
// below: page_rack.js used to carry its own copy, and two copies of the same
// list is the identical drift this file was created to end.
//
// Invariant test: tests/test_platform_coverage.py renders every page in
// headless Chrome and compares the RENDERED option sets against the variant
// directory. A static grep cannot see these options — they do not exist until
// this file runs. It also asserts VARIANT_ORDER has no duplicates and covers
// the RACKDB key set exactly.
"use strict";
(function () {
  // ---- curated display order — AN ORDER HINT ONLY -------------------------
  // Grouped by lifecycle: shipping first, roadmap next, superseded LAST. This
  // list can never hide a platform: order() returns EVERY RACKDB key, and a key
  // missing from this list is appended inside its availability group rather than
  // disappearing. That is the whole difference from the old hand-written option
  // lists.
  const VARIANT_ORDER = [
    // availability:shipping — in production and orderable now (DSX-29).
    // dgx-b300 is the eighth, added by DSX-61: same Blackwell Ultra silicon as
    // hgx-b300 but NVIDIA's own 10U build, and the only Blackwell Ultra rack kW
    // with a PUBLIC citation (4 nodes x ~14 kW).
    "gb300-nvl72", "gb200-nvl72", "b200-liquid", "hgx-b300", "dgx-b300",
    "dgx-b200-aircooled-2su", "gb200-nvl36", "dgx-b200-hd",
    "rubin-nvl144",  // availability:roadmap — badged, every number [A] by rule
    // availability:superseded — LAST and badged. Kept in the list because the
    // set must equal the YAML set (calc_regression.mjs asserts it) and because
    // "why is there no H100 option?" deserves an answer on the page rather than
    // a silent omission. The badge is what stops it reading as a live choice.
    "dgx-h200", "dgx-h100",
  ];

  // availability rank — the GROUPING above, enforced for keys the hint omits
  // too. An unknown availability string sorts with "superseded" (last) so a new
  // value can never silently jump to the head of the list and read as shipping.
  const RANK = { shipping: 0, roadmap: 1, superseded: 2 };

  // "forward-looking" has appeared as a synonym for "roadmap" in variant YAML.
  // Normalise it, or a synonym slips past both the rank and the badge and the
  // platform renders as a shipping SKU.
  const AVAIL_ALIAS = { "forward-looking": "roadmap" };

  // Availability badges. A preliminary or withdrawn spec must never read as a
  // shipping SKU — spec §F3: "Rubin NVL144 is forward-looking and must be
  // labelled as such". Both the long and the short form carry the words, so a
  // compact selector cannot drop the warning.
  const BADGE = {
    roadmap: {
      long: " — ROADMAP: forward-looking, preliminary (every number [A])",
      short: " · forward-looking",
    },
    superseded: {
      long: " — SUPERSEDED, not procurable 2026 (reference only)",
      short: " · superseded",
    },
  };

  const db = () => globalThis.RACKDB || {};

  const P = {
    /** The curated order hint (exported so the regen guard and tests can read it). */
    VARIANT_ORDER: VARIANT_ORDER,

    /** Lifecycle badge text, exported so a page can explain its own badges. */
    BADGE: BADGE,

    /**
     * Every platform in RACKDB, in display order.
     * @returns {string[]} ordered platform keys — never a subset
     */
    order() {
      const D = db();
      const hint = new Map(VARIANT_ORDER.map((k, i) => [k, i]));
      const rank = (k) => {
        const a = this.availabilityOf(k);
        return Object.prototype.hasOwnProperty.call(RANK, a) ? RANK[a] : RANK.superseded;
      };
      return Object.keys(D).sort((a, b) => {
        const ra = rank(a), rb = rank(b);
        if (ra !== rb) return ra - rb;
        // unlisted keys sort after listed ones, then alphabetically — visible,
        // just not curated
        const ha = hint.has(a) ? hint.get(a) : Number.MAX_SAFE_INTEGER;
        const hb = hint.has(b) ? hint.get(b) : Number.MAX_SAFE_INTEGER;
        if (ha !== hb) return ha - hb;
        return a < b ? -1 : a > b ? 1 : 0;
      });
    },

    /** Alias kept for call sites that read "all platforms". */
    getAll() {
      return this.order();
    },

    /**
     * Platforms with a shipped per-variant row GLB on the 3D page.
     * gen_glb.py emits exactly one row model per variant YAML, so this is the
     * whole set; tests/test_platform_coverage.py enforces that
     * assets/models/<key>.glb exists for every variant, which is what keeps
     * this from becoming a second hand-maintained list.
     * @returns {string[]}
     */
    getWithModels() {
      return this.order();
    },

    /**
     * Platforms with a bespoke interior detail model (rack studio).
     * A genuine subset: each detail model is hand-authored interior geometry,
     * not a procedural row. Argued exemption recorded in
     * workstations/power/PLATFORM_COVERAGE_REPORT.md.
     * @returns {string[]}
     */
    getWithDetailModels() {
      const D = globalThis.DETAILRACKS;
      if (!D) return [];
      const have = new Set(Object.keys(D));
      const ordered = this.order().filter((k) => have.has(k));
      // include any detail model whose platform is not in RACKDB at all, so a
      // detail entry can never be hidden either
      for (const k of Object.keys(D).sort()) if (!ordered.includes(k)) ordered.push(k);
      return ordered;
    },

    /** @returns {string} availability from the variant YAML, alias-normalised, or "" */
    availabilityOf(key) {
      const v = db()[key];
      const raw = (v && v.availability) || "";
      return Object.prototype.hasOwnProperty.call(AVAIL_ALIAS, raw)
        ? AVAIL_ALIAS[raw] : raw;
    },

    /** @returns {boolean} true when the platform is not a shipping SKU */
    isRoadmap(key) {
      return this.availabilityOf(key) === "roadmap";
    },

    /** Fallback label for a key with no RACKDB entry (e.g. "hgx-b300" → "HGX B300"). */
    formatKey(key) {
      return String(key).split("-").map((s) => s.toUpperCase()).join(" ");
    },

    /**
     * Display label for a platform, including its availability badge.
     * @param {string} key
     * @param {boolean} short - compact form (parenthetical config dropped)
     * @returns {string}
     */
    labelFor(key, short) {
      const v = db()[key];
      const full = (v && v.platform) || this.formatKey(key);
      const base = short ? this._shortBase(key, full) : full;
      const badge = BADGE[this.availabilityOf(key)];
      return badge ? base + (short ? badge.short : badge.long) : base;
    },

    /** Back-compat name. */
    getLabel(key) {
      return this.labelFor(key, false);
    },

    /** Back-compat name. */
    getShortLabel(key) {
      return this.labelFor(key, true);
    },

    /**
     * Compact base label: drop the parenthetical rack configuration
     * ("DGX B200 (4 systems/rack, high-density air)" → "DGX B200") — BUT only
     * when the result stays unique. Two platforms rendering as the same string
     * would make the selector lie about which one is picked, so a collision
     * keeps the full label. (dgx-b200-aircooled-2su vs dgx-b200-hd hit this.)
     * @private
     */
    _shortBase(key, full) {
      const strip = (s) => s.replace(/\s*\(.*$/, "").trim();
      const cand = strip(full);
      if (!cand) return full;
      const D = db();
      let collisions = 0;
      for (const k of Object.keys(D)) {
        const other = (D[k] && D[k].platform) || this.formatKey(k);
        if (strip(other) === cand) collisions += 1;
      }
      return collisions > 1 ? full : cand;
    },

    /**
     * [value, label] pairs for the app.js field factory.
     * @param {Object} [o]
     * @param {boolean} [o.detailOnly] restrict to platforms with detail models
     * @param {boolean} [o.short] compact labels
     * @param {boolean} [o.includeNone] prepend an empty "no platform" option
     * @param {string}  [o.noneLabel] label for that empty option
     * @returns {Array<[string,string]>}
     */
    optionPairs(o) {
      const opt = o || {};
      const keys = opt.detailOnly ? this.getWithDetailModels() : this.order();
      const pairs = keys.map((k) => [k, this.labelFor(k, !!opt.short)]);
      if (opt.includeNone) {
        pairs.unshift(["", opt.noneLabel || "(none — page default basis)"]);
      }
      return pairs;
    },

    /**
     * Populate a <select> from the variant set.
     * @param {HTMLSelectElement} select
     * @param {Object} [options] see optionPairs, plus:
     * @param {boolean} [options.shortLabels] alias of options.short
     * @param {string}  [options.selectedKey] value to pre-select if offered
     */
    populateSelect(select, options) {
      if (!select) return;
      const o = options || {};
      const short = o.short !== undefined ? o.short : !!o.shortLabels;
      const pairs = this.optionPairs({
        detailOnly: o.detailOnly,
        short: short,
        includeNone: o.includeNone,
        noneLabel: o.noneLabel,
      });
      const frag = document.createDocumentFragment();
      for (const [value, label] of pairs) {
        const opt = document.createElement("option");
        opt.value = value;
        opt.textContent = label;
        const avail = this.availabilityOf(value);
        if (avail) opt.dataset.availability = avail;
        if (this.isRoadmap(value)) opt.dataset.roadmap = "true";
        frag.appendChild(opt);
      }
      select.replaceChildren(frag);
      const want = o.selectedKey;
      if (want && pairs.some(([v]) => v === want)) select.value = want;
    },
  };

  globalThis.AIDC = globalThis.AIDC || {};
  globalThis.AIDC.platforms = P;
})();
